<script setup lang="ts">
import {computed,reactive} from 'vue';
import type {Component,Database} from '../shared/types';
import {coolingControls,coolingPowerConnectors} from '../shared/types';
import {nextComponentId,componentReferences,type ComponentCollection} from '../shared/component-editor';
import ComponentRecordList from './ComponentRecordList.vue';
const props=defineProps<{component:Component;db:Database}>();
const selected=reactive({devices:0,headers:0,groups:0});
const device=computed(()=>props.component.specs.coolingDevices?.[selected.devices]),header=computed(()=>props.component.specs.coolingHeaders?.[selected.headers]),group=computed(()=>props.component.specs.coolingHeaderGroups?.[selected.groups]);
const consumer=computed(()=>['Fan','Cooler'].includes(props.component.category)||props.component.specs.coolingDevices!==undefined);
const provider=computed(()=>['Motherboard','Bay accessory'].includes(props.component.category)||props.component.specs.coolingHeaders!==undefined);
const hasSata=computed(()=>props.component.specs.coolingDevices?.some(d=>d.powerConnector==='SATA power'));
const refs=(key:ComponentCollection,id:string)=>componentReferences(props.component,key,id,props.db);
function optional(row:object,key:string,value:unknown,numeric=false){const record=row as Record<string,unknown>;if(value===''||value==null)delete record[key];else record[key]=numeric?Number(value):value;}
function addDevice(kind:'fan'|'pump'){const list=props.component.specs.coolingDevices??=[];list.push({id:nextComponentId(kind==='fan'?'FAN':'PUMP',list),kind,count:1});selected.devices=list.length-1;}
function addHeader(){const list=props.component.specs.coolingHeaders??=[];list.push({id:nextComponentId('FAN_HEADER',list)});selected.headers=list.length-1;}
function addGroup(){const list=props.component.specs.coolingHeaderGroups??=[];list.push({id:nextComponentId('HEADER_GROUP',list)});selected.groups=list.length-1;}
const deviceItems=computed(()=>props.component.specs.coolingDevices?.map(d=>({id:d.id,summary:`${d.name||d.kind} × ${d.count??1} · ${d.powerConnector||'Power unknown'} · ${d.control||'Control unknown'}`}))||[]);
const headerItems=computed(()=>props.component.specs.coolingHeaders?.map(h=>({id:h.id,summary:`${h.name||'Header'} · ${h.connector||'Connector unknown'} · ${h.maxCurrentA??'?'} A`}))||[]);
const groupItems=computed(()=>props.component.specs.coolingHeaderGroups?.map(g=>({id:g.id,summary:`${g.maxCurrentA??'?'} A shared limit`}))||[]);
const yesNo=[{title:'Unknown',value:null},{title:'Yes',value:true},{title:'No',value:false}];
function remove(kind:'devices'|'headers'|'groups'){const key=kind==='devices'?'coolingDevices':kind==='headers'?'coolingHeaders':'coolingHeaderGroups';const list=props.component.specs[key];const row=list?.[selected[kind]];if(!row||refs(key,row.id).length)return;list!.splice(selected[kind],1);selected[kind]=Math.max(0,selected[kind]-1);}
defineExpose({focusIssue:(path:PropertyKey[])=>{const kind=path[1]==='coolingDevices'?'devices':path[1]==='coolingHeaders'?'headers':'groups';selected[kind]=typeof path[2]==='number'?path[2]:0;}});
// IDs stay stable once added. Referenced rows cannot be removed.
</script>
<template><section class="control-stack">
 <p class="form-hint">Motor power, speed control and RPM feedback are separate. Enter maximum/startup current per motor, not just typical running current. Unknown ratings stay unknown. The optional electrical power in Basics overrides motor estimates; a cooler’s thermal TDP is not electrical draw.</p>
 <template v-if="consumer"><h3>Fans and pumps in this component</h3><div class="heading-actions"><v-btn variant="outlined" :disabled="(component.specs.coolingDevices?.length||0)>=32" @click="addDevice('fan')">Add fan</v-btn><v-btn variant="outlined" :disabled="(component.specs.coolingDevices?.length||0)>=32" @click="addDevice('pump')">Add pump</v-btn></div>
 <ComponentRecordList v-model="selected.devices" label="Cooling devices" :items="deviceItems"><template v-if="device"><div class="form-grid"><v-text-field :model-value="device.id" label="Stable device ID" readonly /><v-text-field v-model="device.name" label="Name (optional)" /><v-select v-model="device.kind" label="Motor type" :items="['fan','pump']" /><v-text-field :model-value="device.count??1" label="Motors per component" type="number" min="1" max="32" @update:model-value="v=>optional(device!,'count',v,true)" /><v-select :model-value="device.powerConnector" label="Motor power connector" :items="coolingPowerConnectors" clearable @update:model-value="v=>optional(device!,'powerConnector',v)" /><v-text-field :model-value="device.voltageV" label="Motor voltage (V)" type="number" min="0" @update:model-value="v=>optional(device!,'voltageV',v,true)" /><v-text-field :model-value="device.currentA" label="Maximum/startup current per motor (A)" type="number" min="0" step="0.01" @update:model-value="v=>optional(device!,'currentA',v,true)" /><v-select :model-value="device.control" label="Speed control" :items="coolingControls" clearable @update:model-value="v=>optional(device!,'control',v)" /><v-select :model-value="device.controlConnector" label="Separate control/RPM plug (if different)" :items="['Fan 3-pin','Fan 4-pin','Proprietary']" clearable @update:model-value="v=>optional(device!,'controlConnector',v)" /><v-select :model-value="device.tachometer??null" label="RPM feedback available" :items="yesNo" @update:model-value="v=>optional(device!,'tachometer',v)" /></div><p class="form-hint">3-pin fans use voltage control; 4-pin PWM uses a separate control signal. A SATA-powered pump still needs its motor power connected independently.</p><p v-if="refs('coolingDevices',device.id).length" class="form-hint">Used by {{refs('coolingDevices',device.id).join(', ')}}.</p><v-btn variant="text" color="error" :disabled="!!refs('coolingDevices',device.id).length" @click="remove('devices')">Remove motor</v-btn></template></ComponentRecordList>
 <template v-if="hasSata"><v-text-field :model-value="component.specs.sataPowerPlugs" label="SATA power plugs used by the whole assembly" type="number" min="0" :disabled="component.specs.sataPowerInputs!==undefined" @update:model-value="v=>optional(component.specs,'sataPowerPlugs',v,true)" /><p class="form-hint">Count physical assembly plugs, not motors. Assign the PSU plug under SATA power wiring in the build. For multiple plugs, name individual inputs in Storage.</p></template>
 </template>
 <template v-if="provider"><h3>Motherboard / controller headers</h3><v-btn variant="outlined" :disabled="(component.specs.coolingHeaders?.length||0)>=64" @click="addHeader">Add header</v-btn><ComponentRecordList v-model="selected.headers" label="Cooling headers" :items="headerItems"><template v-if="header"><div class="form-grid"><v-text-field :model-value="header.id" label="Stable header ID" readonly /><v-text-field v-model="header.name" label="Board label (e.g. CPU_FAN, AIO_PUMP)" /><v-select :model-value="header.connector" label="Header connector" :items="['Fan 3-pin','Fan 4-pin','Proprietary']" clearable @update:model-value="v=>optional(header!,'connector',v)" /><v-select :model-value="header.controlModes||[]" label="Supported control modes" :items="coolingControls" multiple chips clearable @update:model-value="v=>optional(header!,'controlModes',v)" /><v-text-field :model-value="header.voltageV" label="Header supply voltage (V)" type="number" min="0" @update:model-value="v=>optional(header!,'voltageV',v,true)" /><v-text-field :model-value="header.maxCurrentA" label="Header current limit (A)" type="number" min="0" step="0.01" @update:model-value="v=>optional(header!,'maxCurrentA',v,true)" /><v-text-field :model-value="header.maxDevices??1" label="Documented devices including splitter/hub" type="number" min="1" max="32" @update:model-value="v=>optional(header!,'maxDevices',v,true)" /><v-select :model-value="header.tachometer??null" label="RPM monitoring supported" :items="yesNo" @update:model-value="v=>optional(header!,'tachometer',v)" /><v-select :model-value="header.limitGroup" label="Shared current budget" :items="component.specs.coolingHeaderGroups?.map(g=>g.id)||[]" clearable @update:model-value="v=>optional(header!,'limitGroup',v)" /></div><p class="form-hint">One device per header unless a verified splitter or hub is documented. Multiple motors share control and normally only one RPM signal returns.</p><v-btn variant="text" color="error" :disabled="!!refs('coolingHeaders',header.id).length" @click="remove('headers')">Remove header</v-btn></template></ComponentRecordList>
 <h3>Shared current budgets</h3><v-btn variant="outlined" :disabled="(component.specs.coolingHeaderGroups?.length||0)>=32" @click="addGroup">Add shared budget</v-btn><ComponentRecordList v-model="selected.groups" label="Shared header budgets" :items="groupItems"><template v-if="group"><div class="form-grid"><v-text-field :model-value="group.id" label="Stable budget ID" readonly /><v-text-field :model-value="group.maxCurrentA" label="Combined current limit (A)" type="number" min="0" step="0.01" @update:model-value="v=>optional(group!,'maxCurrentA',v,true)" /></div><v-btn variant="text" color="error" :disabled="!!refs('coolingHeaderGroups',group.id).length" @click="remove('groups')">Remove shared budget</v-btn></template></ComponentRecordList>
 </template>
</section></template>
